// Target 2: one fixed-signature GBS step (gbs_step, k_fixed stages) in z = (q, t; p, B): symplectic defect (full and
// on the energy shell), det, reversibility, energy error, vs ds and k. -DCTRL: leapfrog with the 1/(-U) kick.
// Build (from the repository root; logh_ctrl.cpp: python3.11 tests/enzyme/symplectic/make_ctrl.py <dir>):
//   clang++ -std=c++20 -O2 -fplugin=ClangEnzyme-18.so -Isrc/collisional tests/enzyme/symplectic/symp_gbs.cpp -o symp_gbs
//   (Enzyme; -DCTRL -I<dir of logh_ctrl.cpp> for the 1/(-U) kick)
#ifdef CTRL
#include "logh_ctrl.cpp"   // generated by make_ctrl.py
#else
#include "../../../src/collisional/logh.cpp"
#endif
#include "../../../src/collisional/logh_step.cpp"
#include "../../../src/collisional/post_newtonian_core.cpp"
#include "jac.h"

static const int SEQ[] = {2, 4, 6, 8, 12, 16, 24, 32, 48, 64};
static int g_n = 2, g_k = 3;
static double g_mass[LOGH_MAX_BODIES], g_ds = 1e-2;

static void gmap(const double* z, double* out) {
    LogHState s;
    std::memset(&s, 0, sizeof(s));
    const int n3 = 3 * g_n;
    s.n_bodies = g_n;
    for (int i = 0; i < g_n; i++) s.mass[i] = g_mass[i];
    for (int i = 0; i < n3; i++) { s.pos[i] = z[i]; s.vel[i] = z[n3 + 1 + i] / g_mass[i / 3]; }
    s.t = z[n3]; s.B = z[2 * n3 + 1];
    GbsParams par; par.seq = SEQ; par.k_fixed = g_k;
    GbsTable tab; GbsStepOut o;
    gbs_step(par, s, g_ds, tab, -1, nullptr, o);
    for (int i = 0; i < n3; i++) { out[i] = s.pos[i]; out[n3 + 1 + i] = s.vel[i] * g_mass[i / 3]; }
    out[n3] = s.t; out[2 * n3 + 1] = s.B;
}
static void binary(double m1, double m2, double a, double e, double f, double* x1, double* x2, double* v1, double* v2) {
    const double mu = m1 + m2, p = a * (1 - e * e), r = p / (1 + e * std::cos(f));
    const double rx[3] = {r * std::cos(f), r * std::sin(f), 0.0};
    const double rv[3] = {-std::sin(f) * std::sqrt(mu / p), (e + std::cos(f)) * std::sqrt(mu / p), 0.0};
    for (int k = 0; k < 3; k++) { x1[k] = -m2 / mu * rx[k]; x2[k] = m1 / mu * rx[k]; v1[k] = -m2 / mu * rv[k]; v2[k] = m1 / mu * rv[k]; }
}
static void ics(int sys, double e, double* z) {
    const int n3 = 3 * g_n;
    double pos[9] = {}, vel[9] = {};
    if (sys == 2) {
        g_mass[0] = 0.6; g_mass[1] = 0.4;
        binary(0.6, 0.4, 1.0, e, -0.3, pos, pos + 3, vel, vel + 3);
        pos[2] += 0.01; vel[5] += 0.02;
    } else {
        g_mass[0] = 0.5; g_mass[1] = 0.3; g_mass[2] = 0.2;
        double xi[3], xo[3], vi[3], vo[3], X1[3], X2[3], V1[3], V2[3];
        binary(0.5, 0.3, 1.0, e, -0.3, X1, X2, V1, V2);
        binary(0.8, 0.2, 5.0, 0.3, 1.0, xi, xo, vi, vo);
        for (int k = 0; k < 3; k++) {
            pos[k] = X1[k] + xi[k]; pos[3 + k] = X2[k] + xi[k]; pos[6 + k] = xo[k];
            vel[k] = V1[k] + vi[k]; vel[3 + k] = V2[k] + vi[k]; vel[6 + k] = vo[k];
        }
        pos[8] += 0.3; vel[2] += 0.05; vel[5] -= 0.03;
    }
    LogHState s{}; s.n_bodies = g_n;
    for (int i = 0; i < g_n; i++) s.mass[i] = g_mass[i];
    for (int i = 0; i < n3; i++) { s.pos[i] = pos[i]; s.vel[i] = vel[i]; z[i] = pos[i]; z[n3 + 1 + i] = vel[i] * g_mass[i / 3]; }
    z[n3] = 0.0; z[2 * n3 + 1] = -logh_total_energy(s, 1.0);
}
static double energy(const double* z) {
    LogHState s{}; s.n_bodies = g_n; const int n3 = 3 * g_n;
    for (int i = 0; i < g_n; i++) s.mass[i] = g_mass[i];
    for (int i = 0; i < n3; i++) { s.pos[i] = z[i]; s.vel[i] = z[n3 + 1 + i] / g_mass[i / 3]; }
    return logh_total_energy(s, 1.0);
}
static void shell_grad(const double* z, double* g) {
    LogHState s{}; s.n_bodies = g_n; const int n3 = 3 * g_n, d = 2 * (n3 + 1);
    for (int i = 0; i < g_n; i++) s.mass[i] = g_mass[i];
    for (int i = 0; i < n3; i++) { s.pos[i] = z[i]; s.vel[i] = z[n3 + 1 + i] / g_mass[i / 3]; }
    double a[24]; logh_internal_accel(s, 1.0, a);
    for (int j = 0; j < d; j++) g[j] = 0;
    for (int i = 0; i < n3; i++) { g[i] = -g_mass[i / 3] * a[i]; g[n3 + 1 + i] = s.vel[i]; }
    g[2 * n3 + 1] = 1.0;
}
static double M[DMAX][DMAX], Mb[DMAX][DMAX];
int main() {
#ifdef CTRL
    std::printf("# [U-kick]\n");
#else
    std::printf("# [T+B-kick, production]\n");
#endif
    std::printf("# sys e k ds | defect shell det-1 | rev_val rev_jac | |dE/E|\n");
    for (int sys : {2, 3}) {
        g_n = sys; const int d = 2 * (3 * g_n + 1);
        for (double e : {0.5, 0.9, 0.99})
            for (int k : {2, 3, 4, 6, 8})
                for (double ds : {0.3, 0.1, 0.03, 0.01}) {
                    g_k = k; g_ds = ds;
                    double z[DMAX], zo[DMAX], zb[DMAX], g[DMAX];
                    ics(sys, e, z);
                    gmap(z, zo);
                    jac_enzyme<gmap>(z, d, M);
                    shell_grad(z, g);
                    const double sd = symp_defect(M, d), sh = symp_defect_shell(M, d, g), dt = det(M, d) - 1;
                    g_ds = -ds; gmap(zo, zb); jac_enzyme<gmap>(zo, d, Mb); g_ds = ds;
                    double rv = 0; for (int j = 0; j < d; j++) rv = std::max(rv, std::fabs(zb[j] - z[j]) / std::max(1.0, std::fabs(z[j])));
                    std::printf("%d %4.2f %d %5.2f | %8.1e %8.1e %9.1e | %8.1e %8.1e | %8.1e\n", sys, e, k, ds, sd, sh, dt, rv, prod_minus_I(Mb, M, d),
                                std::fabs(energy(zo) / energy(z) - 1));
                }
    }
}
